CREATE OR REPLACE FUNCTION pitlane.lock_job_scope(j uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;BEGIN SELECT * INTO v FROM pitlane.jobs WHERE id=j;IF FOUND THEN PERFORM pg_advisory_xact_lock(hashtextextended(v.tenant_id::text||v.project_id::text,0));END IF;END $$;
CREATE OR REPLACE FUNCTION pitlane.release_reservation(j uuid,billable boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;BEGIN SELECT * INTO v FROM pitlane.jobs WHERE id=j;PERFORM 1 FROM pitlane.budgets WHERE key IN('environment',v.tenant_id::text) ORDER BY key FOR UPDATE;IF v.lot_id IS NOT NULL THEN UPDATE pitlane.entitlement_lots SET reserved=reserved-1,consumed=consumed+CASE WHEN billable THEN 1 ELSE 0 END WHERE id=v.lot_id;END IF;UPDATE pitlane.budgets SET reserved=reserved-v.cost_cap,spent=spent+v.cost_used WHERE key IN('environment',v.tenant_id::text);END $$;
CREATE OR REPLACE FUNCTION pitlane.claim(w text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE j pitlane.jobs;BEGIN IF length(w)<1 OR length(w)>128 THEN RAISE EXCEPTION 'INVALID_WORKER';END IF;SELECT * INTO j FROM pitlane.jobs WHERE state IN('queued','retry_wait') AND ready_at<=now() AND deadline>now() AND attempts<3 AND NOT cancel_requested ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1;IF NOT FOUND THEN RETURN NULL;END IF;UPDATE pitlane.jobs SET state='running',lease_owner=w,lease_until=least(deadline,clock_timestamp()+interval '60 seconds'),lease_epoch=lease_epoch+1,attempts=attempts+1 WHERE id=j.id RETURNING * INTO j;PERFORM pitlane.emit(j.id,'running',jsonb_build_object('attempt',j.attempts,'workerId',w));RETURN to_jsonb(j);END $$;
CREATE OR REPLACE FUNCTION pitlane.heartbeat(j uuid,w text,e bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ BEGIN UPDATE pitlane.jobs SET lease_until=least(deadline,clock_timestamp()+interval '60 seconds') WHERE id=j AND lease_owner=w AND lease_epoch=e AND state IN('running','verifying') AND lease_until>clock_timestamp() AND deadline>clock_timestamp() AND NOT cancel_requested;RETURN FOUND;END $$;
CREATE OR REPLACE FUNCTION pitlane.leased_job(j uuid,w text,e bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;BEGIN SELECT * INTO v FROM pitlane.jobs WHERE id=j AND lease_owner=w AND lease_epoch=e AND state IN('running','verifying') AND lease_until>clock_timestamp() AND deadline>clock_timestamp() AND NOT cancel_requested;IF NOT FOUND THEN RAISE EXCEPTION 'STALE_LEASE';END IF;RETURN to_jsonb(v);END $$;
CREATE OR REPLACE FUNCTION pitlane.cancel_job(j uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;BEGIN PERFORM pitlane.lock_job_scope(j);SELECT * INTO v FROM pitlane.jobs WHERE id=j FOR UPDATE;IF NOT FOUND OR NOT pitlane.can_project(v.tenant_id,v.project_id,true) THEN RAISE EXCEPTION 'NOT_FOUND';END IF;IF v.state IN('completed','unsupported','failed','expired','cancelled') THEN RETURN to_jsonb(v);END IF;UPDATE pitlane.jobs SET state='cancelled',cancel_requested=true,lease_epoch=lease_epoch+1 WHERE id=j RETURNING * INTO v;PERFORM pitlane.release_reservation(j,false);PERFORM pitlane.emit(j,'cancelled');IF v.order_id IS NOT NULL THEN INSERT INTO pitlane.payment_outbox(tenant_id,order_id,business_key,operation) VALUES(v.tenant_id,v.order_id,v.order_id::text||'/cancel','cancel') ON CONFLICT(business_key) DO NOTHING;END IF;RETURN to_jsonb(v);END $$;
CREATE OR REPLACE FUNCTION pitlane.reap() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE target_id uuid;j pitlane.jobs;n integer=0;BEGIN FOR target_id IN SELECT jobs.id FROM pitlane.jobs WHERE state IN('queued','retry_wait','running','verifying','awaiting_payment') AND (deadline<=now() OR lease_until<=now()) ORDER BY tenant_id,project_id,jobs.id LOOP PERFORM pitlane.lock_job_scope(target_id);SELECT * INTO j FROM pitlane.jobs WHERE jobs.id=target_id FOR UPDATE;IF j.state NOT IN('queued','retry_wait','running','verifying','awaiting_payment') OR (j.deadline>now() AND (j.lease_until IS NULL OR j.lease_until>now())) THEN CONTINUE;END IF;IF j.deadline<=now() OR j.attempts>=3 OR j.cancel_requested THEN UPDATE pitlane.jobs SET state=CASE WHEN j.cancel_requested THEN 'cancelled' ELSE 'expired' END,lease_epoch=lease_epoch+1 WHERE jobs.id=target_id;PERFORM pitlane.release_reservation(target_id,false);PERFORM pitlane.emit(target_id,'expired');ELSE UPDATE pitlane.jobs SET state='retry_wait',ready_at=now(),lease_owner=NULL,lease_until=NULL WHERE jobs.id=target_id;PERFORM pitlane.emit(target_id,'retry_wait',jsonb_build_object('reason','LEASE_EXPIRED'));END IF;n=n+1;END LOOP;RETURN n;END $$;
CREATE OR REPLACE FUNCTION pitlane.register_artifact(j uuid,w text,e bigint,m jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;BEGIN PERFORM pitlane.lock_job_scope(j);SELECT * INTO v FROM pitlane.jobs WHERE id=j FOR UPDATE;PERFORM pitlane.leased_job(j,w,e);IF (m->>'bytes')::bigint>1048576 OR (m->>'bytes')::bigint<0 OR m->>'key' NOT LIKE v.tenant_id::text||'/'||v.project_id::text||'/'||j::text||'/%' THEN RAISE EXCEPTION 'INVALID_ARTIFACT';END IF;INSERT INTO pitlane.artifacts(id,tenant_id,project_id,job_id,lease_epoch,object_key,digest,bytes,content_type,state,expires_at) VALUES((m->>'id')::uuid,v.tenant_id,v.project_id,j,e,m->>'key',m->>'sha256',(m->>'bytes')::bigint,m->>'contentType','hash_verified',now()+interval '90 days');END $$;
CREATE OR REPLACE FUNCTION pitlane.finalize(j uuid,w text,e bigint,r jsonb,a uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;f pitlane.artifacts;billable boolean;BEGIN PERFORM pitlane.lock_job_scope(j);SELECT * INTO v FROM pitlane.jobs WHERE id=j FOR UPDATE;PERFORM pitlane.leased_job(j,w,e);SELECT * INTO f FROM pitlane.artifacts WHERE id=a AND job_id=j AND tenant_id=v.tenant_id AND project_id=v.project_id AND lease_epoch=e AND state='hash_verified';IF NOT FOUND THEN RAISE EXCEPTION 'MISSING_ARTIFACT';END IF;IF r->>'jobId'<>j::text OR r->'input'<>v.input OR r->>'origin'<>v.origin OR r->>'schema'<>'pitlane.receipt.v1' OR r->>'finding' NOT IN('supported','contradicted','insufficient_evidence') THEN RAISE EXCEPTION 'INVALID_RECEIPT';END IF;billable=r->>'finding' IN('supported','contradicted');IF billable AND v.order_id IS NOT NULL THEN PERFORM pitlane.assert_delivery_authorization(v.order_id);END IF;IF v.correction_version_id IS NOT NULL THEN PERFORM pitlane.publish_correction(j,r,a);ELSE INSERT INTO pitlane.receipt_versions(id,receipt_id,tenant_id,project_id,job_id,payload,digest,artifact_id,expires_at) VALUES((r->>'versionId')::uuid,(r->>'id')::uuid,v.tenant_id,v.project_id,j,r,f.digest,a,f.expires_at);INSERT INTO pitlane.receipt_heads VALUES((r->>'id')::uuid,v.tenant_id,v.project_id,(r->>'versionId')::uuid);END IF;UPDATE pitlane.artifacts SET state='published' WHERE id=a;UPDATE pitlane.jobs SET state=CASE WHEN r->>'executionState'='unsupported' THEN 'unsupported' ELSE 'completed' END,receipt_id=(r->>'id')::uuid,lease_owner=NULL,lease_until=NULL WHERE id=j RETURNING * INTO v;PERFORM pitlane.release_reservation(j,billable);IF v.order_id IS NOT NULL THEN PERFORM pitlane.order_delivery(v.order_id,(r->>'versionId')::uuid);END IF;PERFORM pitlane.emit(j,'completed',jsonb_build_object('receiptId',v.receipt_id,'finding',r->>'finding','unitsConsumed',CASE WHEN billable THEN 1 ELSE 0 END));RETURN to_jsonb(v);END $$;
CREATE OR REPLACE FUNCTION pitlane.cost_intent(j uuid,w text,e bigint,p text,m text,maximum bigint) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pitlane AS $$ DECLARE v pitlane.jobs;id uuid;BEGIN SELECT * INTO v FROM pitlane.jobs WHERE jobs.id=j FOR UPDATE;PERFORM pitlane.leased_job(j,w,e);IF maximum<0 OR v.calls>=16 OR v.cost_used+maximum>v.cost_cap THEN RAISE EXCEPTION 'COST_BUDGET_EXHAUSTED';END IF;UPDATE pitlane.jobs SET calls=calls+1,cost_used=cost_used+maximum WHERE jobs.id=j;INSERT INTO pitlane.cost_intents(tenant_id,project_id,job_id,lease_epoch,provider_id,method,maximum_micro) VALUES(v.tenant_id,v.project_id,j,e,p,m,maximum) RETURNING cost_intents.id INTO id;RETURN id;END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA pitlane FROM PUBLIC;
GRANT EXECUTE ON FUNCTION pitlane.claim(text),pitlane.heartbeat(uuid,text,bigint),pitlane.leased_job(uuid,text,bigint),pitlane.reap(),pitlane.register_artifact(uuid,text,bigint,jsonb),pitlane.finalize(uuid,text,bigint,jsonb,uuid),pitlane.cost_intent(uuid,text,bigint,text,text,bigint) TO pitlane_worker;
GRANT EXECUTE ON FUNCTION pitlane.cancel_job(uuid) TO pitlane_web;
